local LimeBurner = {}
local PRODUCTS = {
    quicklime = { name = "Živo apno", limestoneCost = 3, fuelCost = 2, time = 3, cost = 18, quality = 50, description = "Živo apno iz žganega apnenca." },
    slaked_lime = { name = "Ugaslo apno", limestoneCost = 3, waterCost = 1, fuelCost = 2, time = 4, cost = 40, quality = 65, prestige = 1, description = "Ugaslo apno za malto." },
    lime_mortar = { name = "Apnena malta", limestoneCost = 4, sandCost = 2, waterCost = 1, fuelCost = 2, time = 5, cost = 90, quality = 80, prestige = 2, happiness = 1, description = "Apnena malta za zidanje." },
    whitewash = { name = "Apnena belila", limestoneCost = 4, waterCost = 2, fuelCost = 2, time = 7, cost = 200, quality = 88, prestige = 5, happiness = 2, description = "Apnena belila za pobeljevanje." },
    silver_treated_lime = { name = "Srebrno obdelano apno", limestoneCost = 5, silverCost = 1, waterCost = 2, fuelCost = 2, time = 10, cost = 440, quality = 94, prestige = 11, happiness = 3, description = "Apno s srebrno obdelavo za plemiče." },
    royal_grand_lime = { name = "Kraljevski veliki apno", limestoneCost = 8, goldCost = 1, silverCost = 1, jewelCost = 1, sandCost = 2, waterCost = 2, fuelCost = 3, time = 15, cost = 1500, quality = 100, prestige = 33, happiness = 8, description = "Veliko kraljevsko apno z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Apnarska delavnica", cost = { gold = 260, wood = 130, stone = 250 }, upkeep = 6, qualityBonus = 5 },
    lime_kiln = { name = "Apnarska peč", cost = { gold = 900, wood = 280, stone = 500, limestone = 10 }, upkeep = 22, qualityBonus = 18 },
    slaking_house = { name = "Ugaševalnica", cost = { gold = 2300, wood = 350, stone = 700, silver = 30, water = 10 }, upkeep = 58, qualityBonus = 30 },
    royal_lime_atelier = { name = "Kraljevski atelje apna", cost = { gold = 9000, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 40 },
}
LimeBurner.limestoneStock = 22; LimeBurner.fuelStock = 16; LimeBurner.waterStock = 18; LimeBurner.sandStock = 18; LimeBurner.silverStock = 8; LimeBurner.goldStock = 6; LimeBurner.jewelStock = 6
LimeBurner.productStock = {}; LimeBurner.buildings = {}; LimeBurner.maker = nil; LimeBurner.activeMaking = {}; LimeBurner.totalProducts = 0; LimeBurner.dayTimer = 0
function LimeBurner.init() LimeBurner.limestoneStock=22; LimeBurner.fuelStock=16; LimeBurner.waterStock=18; LimeBurner.sandStock=18; LimeBurner.silverStock=8; LimeBurner.goldStock=6; LimeBurner.jewelStock=6; LimeBurner.productStock={}; LimeBurner.buildings={}; LimeBurner.maker=nil; LimeBurner.activeMaking={}; LimeBurner.totalProducts=0; LimeBurner.dayTimer=0; print("[LimeBurner] Royal Lime Burner System initialized (6 products, 4 buildings)") end
function LimeBurner.hireMaker(n,s) s=s or math.random(50,90); local c=500+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; LimeBurner.maker={name=n or ("Apnar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Apnar najet: %s (spretnost: %d)",LimeBurner.maker.name,s),"success") end; return true end
function LimeBurner.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function LimeBurner.build(id) local ok,e=LimeBurner.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(LimeBurner.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function LimeBurner.getQualityBonus() local b=0; for _,bd in ipairs(LimeBurner.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function LimeBurner.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.limestoneCost and LimeBurner.limestoneStock<(d.limestoneCost or 0) then return false,"Premalo apnenca" end; if d.fuelCost and LimeBurner.fuelStock<(d.fuelCost or 0) then return false,"Premalo goriva" end; if d.waterCost and LimeBurner.waterStock<(d.waterCost or 0) then return false,"Premalo vode" end; if d.sandCost and LimeBurner.sandStock<(d.sandCost or 0) then return false,"Premalo peska" end; if d.silverCost and LimeBurner.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and LimeBurner.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and LimeBurner.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #LimeBurner.buildings==0 then return false,"Potrebna delavnica" end; if not LimeBurner.maker then return false,"Potreben apnar" end; return true end
function LimeBurner.make(pt,qty) qty=qty or 5; local ok,e=LimeBurner.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.limestoneCost then LimeBurner.limestoneStock=LimeBurner.limestoneStock-d.limestoneCost*qty end; if d.fuelCost then LimeBurner.fuelStock=LimeBurner.fuelStock-d.fuelCost*qty end; if d.waterCost then LimeBurner.waterStock=LimeBurner.waterStock-d.waterCost*qty end; if d.sandCost then LimeBurner.sandStock=LimeBurner.sandStock-d.sandCost*qty end; if d.silverCost then LimeBurner.silverStock=LimeBurner.silverStock-d.silverCost*qty end; if d.goldCost then LimeBurner.goldStock=LimeBurner.goldStock-d.goldCost*qty end; if d.jewelCost then LimeBurner.jewelStock=LimeBurner.jewelStock-d.jewelCost*qty end; local t=d.time; if LimeBurner.maker then t=math.max(1,t-math.floor(LimeBurner.maker.skill/12)) end; table.insert(LimeBurner.activeMaking,{id="lime_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,quality=d.quality or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function LimeBurner.completeMaking(m) local q=1.0+(LimeBurner.getQualityBonus()/100); if LimeBurner.maker then q=q+(LimeBurner.maker.skill/180) end; q=math.min(2.0,q); LimeBurner.productStock[m.productType]=(LimeBurner.productStock[m.productType] or 0)+m.quantity; LimeBurner.totalProducts=LimeBurner.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if LimeBurner.maker then LimeBurner.maker.itemsMade=LimeBurner.maker.itemsMade+m.quantity; if math.random()<0.20 then LimeBurner.maker.skill=math.min(100,LimeBurner.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Apno izdelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"lime.completed",{productName=m.productName,quality=m.quality}) end end
function LimeBurner.update(dt) if not _G.state then return end; LimeBurner.dayTimer=LimeBurner.dayTimer+dt; if LimeBurner.dayTimer>=30 then LimeBurner.dayTimer=0; for i=#LimeBurner.activeMaking,1,-1 do local m=LimeBurner.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then LimeBurner.completeMaking(m); table.remove(LimeBurner.activeMaking,i) end end; local tu=0; for _,bd in ipairs(LimeBurner.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if LimeBurner.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function LimeBurner.getStats() return {limestoneStock=LimeBurner.limestoneStock,fuelStock=LimeBurner.fuelStock,waterStock=LimeBurner.waterStock,sandStock=LimeBurner.sandStock,silverStock=LimeBurner.silverStock,goldStock=LimeBurner.goldStock,jewelStock=LimeBurner.jewelStock,productStock=LimeBurner.productStock,numBuildings=#LimeBurner.buildings,hasMaker=LimeBurner.maker~=nil,makerName=LimeBurner.maker and LimeBurner.maker.name or "—",makerSkill=LimeBurner.maker and LimeBurner.maker.skill or 0,activeMaking=#LimeBurner.activeMaking,totalProducts=LimeBurner.totalProducts} end
return LimeBurner
